mapper.select:
SELECT subject_id, subject_display_name FROM ( SELECT DISTINCT ON (subject_id) subject_id, subject_display_name, created_at FROM sys_log WHERE subject_id IS NOT NULL AND subject_display_name IS NOT NULL
AND subject_display_name ILIKE '%' || #{search} || '%'
ORDER BY subject_id, created_at DESC ) latest_actor ORDER BY subject_display_name, subject_id LIMIT #{limit} OFFSET #{offset}
